/// <summary>
/// pickup delivery note report controller
/// </summary>
internal final class METDeliveryNoteReportController extends SRSReportRunController
{
}

Method.Source:
/// <summary>Constuct new object</summary>
/// <param name = "_args">Arguments</param>
/// <returns>New Controller Object</returns>
public static METDeliveryNoteReportController construct(Args _args)
{
    METDeliveryNoteReportController controller = new METDeliveryNoteReportController();
    controller.parmArgs(_args);
    controller.parmReportName(ssrsReportStr(METDeliveryNoteReport, Report));
    controller.parmShowDialog(false);

    return controller;
}

/// <summary>
/// The main method of the batch job.
/// </summary>
/// <param name = "_args">The arguments passed by the caller object.</param>
public static void main(Args _args)
{
    SysOperationController          controller      = METDeliveryNoteReportController::construct(_args);
    container                       conShipmentId   = str2con(_args.parm());
    METDeliveryNoteReportContract   contract;

    for(int i =1; conLen(conShipmentId) >= i; i++)
    {
        contract = controller.getDataContractObject() as METDeliveryNoteReportContract;
        contract.parmShipmentID(conPeek(conShipmentId, i));

        controller.startOperation();
    }
}
